from fastapi import FastAPI, HTTPException, Depends, Header
from pydantic import BaseModel, Field
from typing import Dict, List, Optional, Literal
from datetime import datetime
import uvicorn

app = FastAPI(title='Nenios Child Care Management')

roles = {'admin', 'office_staff', 'teacher', 'parent'}

class FamilyIn(BaseModel):
    name: str
    contacts: List[str] = []

class ChildIn(BaseModel):
    family_id: int
    name: str
    age_group: str
    health_info: Dict[str, str] = {}
    immunizations_current: bool = False

class ClassroomIn(BaseModel):
    name: str
    age_group: str
    capacity: int = Field(gt=0)

class EnrollmentIn(BaseModel):
    child_id: int
    classroom_id: int
    status: Literal['pending', 'enrolled', 'waitlisted'] = 'pending'

class InvoiceIn(BaseModel):
    family_id: int
    child_id: int
    amount: float = Field(ge=0)
    description: str = ''

state = {
    'families': {}, 'children': {}, 'classrooms': {}, 'enrollments': {},
    'invoices': {}, 'payments': {}, 'audit': [], 'next_ids': {k: 1 for k in ['family','child','classroom','enrollment','invoice','payment']}
}

def next_id(kind):
    i = state['next_ids'][kind]
    state['next_ids'][kind] += 1
    return i

def current_role(x_role: Optional[str] = Header(default='office_staff')):
    if x_role not in roles:
        raise HTTPException(403, 'invalid role')
    return x_role

def audit(action, entity, entity_id, role, before=None, after=None):
    state['audit'].append({'ts': datetime.utcnow().isoformat(), 'action': action, 'entity': entity, 'entity_id': entity_id, 'role': role, 'before': before, 'after': after})

@app.get('/')
def home():
    return {'service': 'Nenios Child Care Management', 'status': 'ok'}

@app.post('/families')
def create_family(payload: FamilyIn, role: str = Depends(current_role)):
    fid = next_id('family')
    state['families'][fid] = {'id': fid, **payload.model_dump()}
    audit('create', 'family', fid, role, None, state['families'][fid])
    return state['families'][fid]

@app.post('/classrooms')
def create_classroom(payload: ClassroomIn, role: str = Depends(current_role)):
    if role not in {'admin', 'office_staff'}:
        raise HTTPException(403, 'not allowed')
    cid = next_id('classroom')
    state['classrooms'][cid] = {'id': cid, **payload.model_dump()}
    audit('create', 'classroom', cid, role, None, state['classrooms'][cid])
    return state['classrooms'][cid]

@app.post('/children')
def create_child(payload: ChildIn, role: str = Depends(current_role)):
    if payload.family_id not in state['families']:
        raise HTTPException(404, 'family not found')
    cid = next_id('child')
    state['children'][cid] = {'id': cid, **payload.model_dump()}
    audit('create', 'child', cid, role, None, state['children'][cid])
    return state['children'][cid]

@app.get('/enrollment/availability')
def availability(role: str = Depends(current_role)):
    result = []
    for c in state['classrooms'].values():
        enrolled = sum(1 for e in state['enrollments'].values() if e['classroom_id'] == c['id'] and e['status'] == 'enrolled')
        result.append({**c, 'available_spots': c['capacity'] - enrolled})
    return result

@app.post('/enrollments')
def create_enrollment(payload: EnrollmentIn, role: str = Depends(current_role)):
    if payload.child_id not in state['children']:
        raise HTTPException(404, 'child not found')
    if payload.classroom_id not in state['classrooms']:
        raise HTTPException(404, 'classroom not found')
    classroom = state['classrooms'][payload.classroom_id]
    enrolled = sum(1 for e in state['enrollments'].values() if e['classroom_id'] == payload.classroom_id and e['status'] == 'enrolled')
    if payload.status == 'enrolled' and enrolled >= classroom['capacity']:
        raise HTTPException(400, 'classroom full')
    eid = next_id('enrollment')
    state['enrollments'][eid] = {'id': eid, **payload.model_dump()}
    audit('create', 'enrollment', eid, role, None, state['enrollments'][eid])
    return state['enrollments'][eid]

@app.post('/enrollments/{classroom_id}/move-next')
def move_next(classroom_id: int, role: str = Depends(current_role)):
    if classroom_id not in state['classrooms']:
        raise HTTPException(404, 'classroom not found')
    classroom = state['classrooms'][classroom_id]
    open_spots = classroom['capacity'] - sum(1 for e in state['enrollments'].values() if e['classroom_id'] == classroom_id and e['status'] == 'enrolled')
    if open_spots <= 0:
        raise HTTPException(400, 'no available spots')
    candidates = [e for e in state['enrollments'].values() if e['classroom_id'] == classroom_id and e['status'] == 'waitlisted']
    if not candidates:
        raise HTTPException(404, 'no waitlisted child')
    chosen = sorted(candidates, key=lambda e: e['id'])[0]
    before = chosen.copy()
    chosen['status'] = 'enrolled'
    audit('update', 'enrollment', chosen['id'], role, before, chosen.copy())
    return chosen

@app.patch('/children/{child_id}/health')
def update_health(child_id: int, immunizations_current: Optional[bool] = None, note: Optional[str] = None, role: str = Depends(current_role)):
    if child_id not in state['children']:
        raise HTTPException(404, 'child not found')
    before = state['children'][child_id].copy()
    if immunizations_current is not None:
        state['children'][child_id]['immunizations_current'] = immunizations_current
    if note:
        state['children'][child_id].setdefault('health_info', {})['note'] = note
    audit('update', 'child', child_id, role, before, state['children'][child_id].copy())
    return state['children'][child_id]

@app.get('/health/compliance')
def health_compliance(role: str = Depends(current_role)):
    return [{'child_id': c['id'], 'name': c['name'], 'immunizations_current': c.get('immunizations_current', False)} for c in state['children'].values()]

@app.post('/invoices')
def create_invoice(payload: InvoiceIn, role: str = Depends(current_role)):
    if payload.family_id not in state['families'] or payload.child_id not in state['children']:
        raise HTTPException(404, 'family or child not found')
    iid = next_id('invoice')
    state['invoices'][iid] = {'id': iid, **payload.model_dump(), 'paid': 0.0, 'balance': payload.amount}
    audit('create', 'invoice', iid, role, None, state['invoices'][iid])
    return state['invoices'][iid]

@app.post('/payments')
def create_payment(family_id: int, invoice_id: int, amount: float, role: str = Depends(current_role)):
    if invoice_id not in state['invoices']:
        raise HTTPException(404, 'invoice not found')
    inv = state['invoices'][invoice_id]
    if inv['family_id'] != family_id:
        raise HTTPException(400, 'family mismatch')
    pid = next_id('payment')
    state['payments'][pid] = {'id': pid, 'family_id': family_id, 'invoice_id': invoice_id, 'amount': amount}
    inv['paid'] += amount
    inv['balance'] = max(0.0, inv['amount'] - inv['paid'])
    audit('create', 'payment', pid, role, None, state['payments'][pid])
    return state['payments'][pid]

@app.get('/billing/summary')
def billing_summary(role: str = Depends(current_role)):
    return list(state['invoices'].values())

@app.get('/reports/daily')
def daily_report(role: str = Depends(current_role)):
    enrolled = [e for e in state['enrollments'].values() if e['status'] == 'enrolled']
    waitlisted = [e for e in state['enrollments'].values() if e['status'] == 'waitlisted']
    open_spots = {c['id']: c['capacity'] - sum(1 for e in enrolled if e['classroom_id'] == c['id']) for c in state['classrooms'].values()}
    return {'enrollment_count': len(enrolled), 'waitlist_count': len(waitlisted), 'open_spots': open_spots, 'unpaid_invoices': [i for i in state['invoices'].values() if i['balance'] > 0], 'health_reminders': [c for c in state['children'].values() if not c.get('immunizations_current', False)]}

@app.get('/audit')
def get_audit(role: str = Depends(current_role)):
    return state['audit']

if __name__ == '__main__':
    uvicorn.run(app, host='0.0.0.0', port=8000)
EOF

