from fastapi.testclient import TestClient
from app import app

client = TestClient(app)

headers = {'X-Role': 'office_staff'}

def test_workflow():
    fam = client.post('/families', json={'name': 'Smith', 'contacts': ['555-1111']}, headers=headers).json()
    cls = client.post('/classrooms', json={'name': 'Sunflowers', 'age_group': 'toddler', 'capacity': 1}, headers=headers).json()
    child1 = client.post('/children', json={'family_id': fam['id'], 'name': 'Ava', 'age_group': 'toddler', 'immunizations_current': False}, headers=headers).json()
    child2 = client.post('/children', json={'family_id': fam['id'], 'name': 'Ben', 'age_group': 'toddler', 'immunizations_current': True}, headers=headers).json()
    e1 = client.post('/enrollments', json={'child_id': child1['id'], 'classroom_id': cls['id'], 'status': 'enrolled'}, headers=headers)
    assert e1.status_code == 200
    e2 = client.post('/enrollments', json={'child_id': child2['id'], 'classroom_id': cls['id'], 'status': 'waitlisted'}, headers=headers)
    assert e2.status_code == 200
    avail = client.get('/enrollment/availability', headers=headers).json()
    assert avail[0]['available_spots'] == 0
    moved = client.post(f'/enrollments/{cls["id"]}/move-next', headers=headers)
    assert moved.status_code == 400
    health = client.get('/health/compliance', headers=headers).json()
    assert any(not x['immunizations_current'] for x in health)
    inv = client.post('/invoices', json={'family_id': fam['id'], 'child_id': child1['id'], 'amount': 100, 'description': 'Tuition'}, headers=headers).json()
    pay = client.post('/payments?family_id=%s&invoice_id=%s&amount=40' % (fam['id'], inv['id']), headers=headers)
    assert pay.status_code == 200
    summary = client.get('/billing/summary', headers=headers).json()
    assert summary[0]['balance'] == 60
    report = client.get('/reports/daily', headers=headers).json()
    assert report['enrollment_count'] == 1
    audit = client.get('/audit', headers=headers).json()
    assert len(audit) >= 7
